seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)
comp={"A":"T","T":"A","G":"C","C":"G"}
def rc(s): return "".join(comp[c] for c in reversed(s))

# find approximate inverted repeats: length L, compare seq[i:i+L] with rc(seq[j:j+L]) mismatches<=m
def find_IR(L, maxmm, minspread=20):
    out=[]
    for i in range(n-L+1):
        a=seq[i:i+L]
        ra=rc(a)
        for j in range(i+minspread, n-L+1):
            b=seq[j:j+L]
            mm=sum(1 for x,y in zip(ra,b) if x!=y)
            if mm<=maxmm:
                out.append((i, i+L-1, j, j+L-1, mm))
    return out

for L in (30,25,20,15,12,10):
    res=find_IR(L, 2 if L>=15 else 1)
    # keep only ones with large spacing (potential IR at ends of an element)
    big=[r for r in res if r[2]-r[1]>800]
    print("L=",L,"total IR pairs:",len(res),"with spacer>800:",len(big))
    for r in big[:20]:
        print("   ",r, seq[r[0]:r[1]+1], "|", seq[r[2]:r[3]+1])
