def extend(i,j,mm=3):
    # i start of left arm going forward, j start of right arm (so left arm is seq[i:i+L], right arm rc'ed = seq[j:j+L])
    # extend to the right (increasing L)
    L=K
    while i+L < j and j+L <= n:
        if seq[i+L]==comp[seq[j+L-1]]:
            L+=1
        else:
