import random
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)
stops={"TAA","TAG","TGA"}
comp={"A":"T","T":"A","G":"C","C":"G"}
rc=lambda s:"".join(comp[c] for c in reversed(s))

# Build a first-order Markov model from the whole region
from collections import Counter
tr=Counter()
for i in range(n-1):
    tr[seq[i]+seq[i+1]]+=1
bases="ACGT"
def gen(L, start=None):
    if start is None:
        start=random.choice(bases)
    out=[start]
    for _ in range(L-1):
        c=out[-1]
        tot=sum(tr[c+b] for b in bases)
        r=random.random()*tot
        acc=0
        for b in bases:
            acc+=tr[c+b]
            if r<=acc:
                out.append(b); break
    return "".join(out)

def longest_orf_stats(s):
    best=None
    nn=len(s)
    for f in range(3):
        start=None; i=f
        while i+3<=nn:
            cod=s[i:i+3]
            if cod=="ATG" and start is None: start=i
            if cod in stops:
                if start is not None:
                    if best is None or i-start>best[0]: best=(i-start,start,i+2)
                start=None
            i+=3
    if best is None: return None
    L,a,b=best
    o=s[a:b+1]
    g=lambda x:(x.count("G")+x.count("C"))/len(x)*100
    return L, g(o[0::3]), g(o[1::3]), g(o[2::3])

res=[]
for _ in range(300):
    s=gen(3000)
    st=longest_orf_stats(s)
    if st: res.append(st)
res.sort()
import statistics
Ls=[r[0] for r in res]
print("simulated longest ORF length: median",statistics.median(Ls),"90th",Ls[int(0.9*len(Ls))],"max",max(Ls))
# GC3 - GC1 for those with length>600
long_ones=[r for r in res if r[0]>=700]
print("num simulated ORFs >=700bp:",len(long_ones))
for r in sorted(long_ones,reverse=True)[:15]:
    print("  len",r[0],"GC1 %.0f GC2 %.0f GC3 %.0f"%(r[1],r[2],r[3]))
print()
print("observed: len 714 (fwd237-953 rev) GC1 47 GC2 47 GC3 37")
print("observed: len 1017 (fwd1160-2177) GC1 56 GC2 37 GC3 71")
"}

