import random, statistics
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)
stops={"TAA","TAG","TGA"}
comp={"A":"T","T":"A","G":"C","C":"G"}
rc=lambda s:"".join(comp[c] for c in reversed(s))
from collections import Counter
tr=Counter()
for i in range(n-1): tr[seq[i]+seq[i+1]]+=1
bases="ACGT"
def gen(L):
    out=[random.choice(bases)]
    for _ in range(L-1):
        c=out[-1]; tot=sum(tr[c+b] for b in bases); r=random.random()*tot; acc=0
        for b in bases:
            acc+=tr[c+b]
            if r<=acc: out.append(b); break
    return "".join(out)
def longest_orf(s):
    best=None; nn=len(s)
    for strand in (s, rc(s)):
        for f in range(3):
            start=None; i=f
            while i+3<=nn:
                cod=strand[i:i+3]
                if cod=="ATG" and start is None: start=i
                if cod in stops:
                    if start is not None and (best is None or i-start>best[0]): best=(i-start,start,i+2,strand)
                    start=None
                i+=3
    return best
Ls=[]
for _ in range(200):
    s=gen(3000)
    b=longest_orf(s)
    if b: Ls.append(b[0])
Ls.sort()
print("6-frame simulated longest ORF: median",statistics.median(Ls),"max",max(Ls),"90th",Ls[int(0.9*len(Ls))])
print("observed ORFs: 714, 1017")
print("num >=714:",sum(1 for x in Ls if x>=714),"/",len(Ls))
